package com.infosoft.sira.cancelacion;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.security.Principal;import java.util.*;
@RestController @RequestMapping("/api/v1/cancelaciones") public class CancelacionController{
 private final JdbcTemplate db; public CancelacionController(JdbcTemplate db){this.db=db;}
 @GetMapping("/tipos-motivo") public List<Map<String,Object>> tipos(){return db.queryForList("select id_tipo_motivo id,codigo,nombre,descripcion,requiere_observacion from sira.cat_tipo_motivo_cancelacion where activo=true order by orden,nombre");}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> crear(@Valid @RequestBody Crear r,@RequestHeader(value="X-Forwarded-For",required=false)String ip,@RequestHeader(value="User-Agent",required=false)String ua){Long id=db.queryForObject("insert into sira.per_solicitud_cancelacion(id_persona,motivo_inicial,correo_contacto,direccion_ip,user_agent,id_tipo_motivo) values(?,?,?,?,?,(select id_tipo_motivo from sira.cat_tipo_motivo_cancelacion where codigo='PENDIENTE')) returning id_solicitud",Long.class,r.personaId(),r.motivoInicial(),r.correo(),ip,ua);return Map.of("idSolicitud",id,"estado","RECIBIDA");}
 @GetMapping public List<Map<String,Object>> listar(){return db.queryForList("select c.*,t.nombre tipo_motivo from sira.per_solicitud_cancelacion c left join sira.cat_tipo_motivo_cancelacion t on t.id_tipo_motivo=c.id_tipo_motivo where c.activo=true order by c.fecha_solicitud desc");}
 @PutMapping("/{id}/clasificacion") @Transactional public Map<String,Object> clasificar(@PathVariable long id,@Valid @RequestBody Clasificar r,Principal p){String u=p==null?"sistema":p.getName();int n=db.update("update sira.per_solicitud_cancelacion set id_tipo_motivo=?,estado=?,observacion_administrativa=?,fecha_tipificacion=clock_timestamp(),usuario_tipificacion=?,tipo_asignacion=case when fecha_tipificacion is null then 'MANUAL' else 'CORREGIDA' end where id_solicitud=? and activo=true",r.tipoMotivoId(),r.estado(),r.observacion(),u,id);if(n==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);return Map.of("actualizado",true);}
 public record Crear(@NotNull Long personaId,@NotBlank @Size(max=2000)String motivoInicial,@Size(max=254)String correo){} public record Clasificar(@NotNull Long tipoMotivoId,@NotBlank String estado,@Size(max=2000)String observacion){}
}
